"""Protocol amendment 6: the confirmation (amendment 5) on the SAME six tasks generated by the v1 frozen code
(confirm_tasks.json), with the outcome-neutral reordering and the 60 s per-fit budget.

  python mission-03/experiments/p1_composition/run_confirm2.py
"""

from __future__ import annotations

import json
from pathlib import Path

import run_amend34
from run_confirm import CondTask

HERE = Path(__file__).resolve().parent

if __name__ == "__main__":
    spec = json.loads((HERE / "confirm_tasks.json").read_text())
    tasks = {}
    for k, p in spec["tasks"].items():
        p = {"commands": [(c, m) for c, m in p["commands"]], "cond": tuple(p["cond"])}
        tasks[k] = CondTask(k, p)
    print("tasks from v1 frozen code", spec["frozen_code_sha256"], flush=True)
    run_amend34.main(uids=tuple(tasks), units=tasks, out_name="confirm2.json")
